// Generational Playbook icon mark — transparent PNG, provided directly by Karina (9/25) after
// repeated attempts to hand-redraw the vector logo in jsPDF kept producing subtle discrepancies
// (tapered/pointed stroke ends instead of flat-cut ends, then a thinner-line complaint) that were
// hard to pin down and fix with confidence via manual path math. Using the real asset directly
// sidesteps all of that — this is the actual mark, pixel for pixel, cropped tight to its content
// bbox with a few px of padding and downsampled to 500px wide (plenty for print at the ~20pt size
// this renders at in the header). Aspect ratio (width/height) is 500/469 = 1.0661 — use this
// whenever sizing it in jsPDF so it never stretches.
export const LOGO_MARK_ASPECT = 500 / 469;
export const LOGO_MARK_PNG_BASE64 =
  "data:image/png;base64,";
